<?php
namespace App\Livewire;
use App\Models\CashPoolEntry;use App\Models\PayrollRun;use App\Models\User;use Illuminate\Support\Facades\Auth;use Illuminate\Support\Facades\DB;use Livewire\Attributes\Layout;use Livewire\Component;
#[Layout('layouts.app')] class Payroll extends Component { public string $period=''; public ?int $payingId=null; public function mount():void{$this->period=now()->format('Y-m');} public function pay(int $id):void{$this->payingId=$id;} public function confirm():void{abort_unless(Auth::user()->hasPermission('staff.payroll'),403);$school=Auth::user()->school;$term=$school->currentTerm();$staff=User::where('school_id',$school->id)->where('employment_status','active')->findOrFail($this->payingId);if(PayrollRun::where('user_id',$staff->id)->where('period',$this->period)->exists()){session()->flash('error','This staff member has already been paid for this period.');return;}DB::transaction(function()use($school,$term,$staff){$run=PayrollRun::create(['school_id'=>$school->id,'term_id'=>$term?->id,'period'=>$this->period,'user_id'=>$staff->id,'amount'=>$staff->base_salary,'paid_at'=>now(),'recorded_by'=>Auth::id()]);CashPoolEntry::create(['school_id'=>$school->id,'term_id'=>$term?->id,'payroll_run_id'=>$run->id,'direction'=>'debit','amount'=>$run->amount,'description'=>'Payroll: '.$staff->name.' · '.$this->period,'transacted_at'=>now(),'recorded_by'=>Auth::id()]);});$this->payingId=null;session()->flash('status','Payroll posted and deducted from the cash pool.');} public function render(){ $school=Auth::user()->school;return view('livewire.payroll',['staff'=>User::where('school_id',$school->id)->where('employment_status','active')->orderBy('name')->get(),'runs'=>PayrollRun::with('staff')->where('school_id',$school->id)->latest('paid_at')->get(),'pageTitle'=>'Payroll']);} }
